from datetime import datetime, timedelta

class Scheduler:
    def __init__(self) -> None:
        self.appointments = {}  # appointment_id -> {patient, doctor, start, end, cancelled}
        self.next_id = 1
        self.patient_appointments = {}  # patient -> list of appointment_ids

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        # Requirement 4: Booking an appointment that starts before `now` raises ValueError
        if start < now:
            raise ValueError("Appointment cannot start before current time")

        # Requirement 1: Check for overlapping appointments for the same doctor
        for appointment_id, appointment in self.appointments.items():
            if not appointment.get('cancelled', False) and appointment['doctor'] == doctor:
                # Check if there's overlap between [start, end] and [appointment['start'], appointment['end']]
                if not (end <= appointment['start'] or start >= appointment['end']):
                    raise ValueError("Doctor is not available during the requested time slot")

        # Requirement 3: A patient can have at most one upcoming appointment
        # Find all upcoming appointments for this patient
        upcoming_patient_appointments = []
        for appointment_id, appointment in self.appointments.items():
            if not appointment.get('cancelled', False) and appointment['patient'] == patient:
                if appointment['start'] > now:
                    upcoming_patient_appointments.append(appointment_id)

        if len(upcoming_patient_appointments) >= 1:
            raise ValueError("Patient already has an upcoming appointment")

        # Create new appointment
        appointment_id = self.next_id
        self.next_id += 1

        self.appointments[appointment_id] = {
            'patient': patient,
            'doctor': doctor,
            'start': start,
            'end': end,
            'cancelled': False
        }

        # Track patient's appointments
        if patient not in self.patient_appointments:
            self.patient_appointments[patient] = []
        self.patient_appointments[patient].append(appointment_id)

        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self.appointments:
            raise ValueError("Appointment does not exist")

        appointment = self.appointments[appointment_id]

        # If appointment is already cancelled, do nothing
        if appointment.get('cancelled', False):
            return

        # Requirement 2: Cancelling an appointment less than 24 hours before its start 
        # does not free the time slot; the slot stays blocked.
        # We still mark it as cancelled but don't free the slot (so no special handling needed here)
        # since our is_free method will check for cancelled appointments with the 24-hour rule

        # Mark as cancelled
        appointment['cancelled'] = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        # Check all appointments for this doctor
        for appointment_id, appointment in self.appointments.items():
            # Skip cancelled appointments that are more than 24 hours before their start time
            if appointment.get('cancelled', False):
                # If cancelled less than 24 hours before start, it's still blocked
                # If cancelled 24+ hours before start, it's freed
                if appointment['start'] - now >= timedelta(hours=24):
                    continue

            # Skip non-cancelled appointments or cancelled ones that are still blocking
            if not appointment.get('cancelled', False) or (appointment['start'] - now < timedelta(hours=24)):
                if appointment['doctor'] == doctor:
                    # Check for overlap
                    if not (end <= appointment['start'] or start >= appointment['end']):
                        return False

        return True
